// ═══════════════════════════════════════════════════════
// 節點②：訂單驗證與清洗
// 功能：清洗姓名空白、驗證電話、處理備註空值、補全訂單號
// ═══════════════════════════════════════════════════════
const item  = $input.first();
const order = item.json;

// 1. 姓名清洗（去除前後空白）
const customerName = (order.customerName || '').trim();
if (!customerName) throw new Error('顧客姓名不能為空');

// 2. 電話格式驗證（10 碼純數字）
const phone = String(order.phone || '').trim();
if (!/^\d{10}$/.test(phone)) {
  throw new Error('電話格式不正確（需 10 位數字）：' + phone);
}

// 3. 備註欄空值判斷
const orderNote = (order.orderNote || '').trim();
const hasNote   = orderNote.length > 0;

// 4. 訂單時間轉換（若缺失則使用當下時間）
const orderTime = new Date(order.orderTime || new Date().toISOString());

// 5. 品項非空驗證
const items = Array.isArray(order.items) ? order.items : [];
if (items.length === 0) throw new Error('訂單品項不能為空');

// 6. 補全訂單流水號（若前端未提供）
const todayStr = new Date().toLocaleDateString('zh-TW', { timeZone: 'Asia/Taipei' })
                           .replace(/\//g, '');
const seq      = String(Math.floor(Math.random() * 9000) + 1000);
const orderId  = order.orderId || (todayStr + '-' + seq);

return [{
  json: {
    orderId,
    customerName,
    phone,
    dineIn:    Boolean(order.dineIn ?? true),
    tableNo:   order.tableNo || '—',
    orderNote: hasNote ? orderNote : '',
    hasNote,
    orderTime:  orderTime.toISOString(),
    items,
    receivedAt: new Date().toISOString()
  }
}];

// ═══════════════════════════════════════════════════════
// 節點④：品項金額計算
// 功能：過濾有效品項、計算含稅金額、組裝 LINE 廚房通知訊息
// ═══════════════════════════════════════════════════════
const order = $input.first().json;

// 1. 過濾有效品項（qty > 0）
const validItems = (order.items || [])
  .filter(i => (i.qty || 0) > 0)
  .map(i => ({
    itemId:   i.itemId,
    name:     i.name,
    qty:      i.qty,
    price:    i.price,
    subtotal: i.price * i.qty
  }));

if (validItems.length === 0) throw new Error('無有效品項（所有品項數量為 0）');

// 2. 金額計算（含 5% 稅，四捨五入）
const subtotal     = validItems.reduce((s, i) => s + i.subtotal, 0);
const totalWithTax = Math.round(subtotal * 1.05);
const taxAmount    = totalWithTax - subtotal;
const formattedTotal = 'NT$' + totalWithTax.toLocaleString('zh-TW');

// 3. 廚房通知資料組裝
const itemNameList = validItems.map(i => i.name + ' ×' + i.qty).join('、');
const pickupCode   = order.orderId.replace(/[^0-9A-Za-z]/g, '').slice(-8).toUpperCase();

// 4. 台灣時間格式化
const timeStr = new Date(order.orderTime).toLocaleTimeString('zh-TW', {
  timeZone: 'Asia/Taipei', hour: '2-digit', minute: '2-digit', hour12: false
});

// 5. 組裝 LINE 廚房通知訊息（各行以 \n 換行）
const msgLines = [
  '🧾 新訂單 #' + order.orderId,
  '⏰ ' + timeStr,
  '🪑 ' + (order.dineIn ? '內用 ' + (order.tableNo || '—') : '外帶'),
  '',
  '📋 品項：' + itemNameList,
  '💰 合計：' + formattedTotal + '（含稅）',
  '🎫 取餐碼：' + pickupCode
];
if (order.hasNote && order.orderNote) {
  msgLines.push('📝 備註：' + order.orderNote);
}
const lineMessage = msgLines.join('\n');

return [{
  json: {
    ...order,
    validItems,
    itemCount:          validItems.length,
    itemNameList,
    subtotal,
    taxAmount,
    totalWithTax,
    formattedTotal,
    pickupCode,
    orderTimeFormatted: timeStr,
    lineMessage
  }
}];

