// ═══════════════════════════════════════════════════════
// 日結流程 節點②：模擬當日訂單資料
// ── 測試用途：直接在此節點產生假訂單資料 ──────────────
// ── 正式上線時的替換方式 ──────────────────────────────
// 1. 刪除此 Code 節點
// 2. 加入 HTTP Request 節點，設定：
//    Method: GET
//    URL:    https://your-pos-api.example.com/api/orders
//    Query:  date={{ $today.toFormat('yyyy-MM-dd') }}&status=all
// ═══════════════════════════════════════════════════════
const today = $today.toFormat('yyyyMMdd');

const mockOrders = [
  {
    orderId: today + '-0001',
    customerName: '王小明', phone: '0912345678',
    dineIn: true, tableNo: 'A3', status: 'done',
    totalWithTax: 147,
    validItems: [
      { name: '總匯蛋餅', qty: 2, price: 55, subtotal: 110 },
      { name: '大杯豆漿', qty: 1, price: 30, subtotal: 30 }
    ]
  },
  {
    orderId: today + '-0002',
    customerName: '李美玲', phone: '0923456789',
    dineIn: false, tableNo: '—', status: 'done',
    totalWithTax: 84,
    validItems: [
      { name: '火腿蛋土司', qty: 1, price: 45, subtotal: 45 },
      { name: '中杯奶茶',   qty: 1, price: 35, subtotal: 35 }
    ]
  },
  {
    orderId: today + '-0003',
    customerName: '張大偉', phone: '0934567890',
    dineIn: true, tableNo: 'B1', status: 'done',
    totalWithTax: 210,
    validItems: [
      { name: '總匯蛋餅',   qty: 2, price: 55, subtotal: 110 },
      { name: '培根起司堡', qty: 1, price: 65, subtotal: 65 },
      { name: '大杯紅茶',   qty: 1, price: 25, subtotal: 25 }
    ]
  },
  {
    orderId: today + '-0004',
    customerName: '陳小芳', phone: '0945678901',
    dineIn: true, tableNo: 'C2', status: 'cancelled',
    totalWithTax: 0, validItems: []
  },
  {
    orderId: today + '-0005',
    customerName: '林志明', phone: '0956789012',
    dineIn: false, tableNo: '—', status: 'done',
    totalWithTax: 63,
    validItems: [
      { name: '起司蛋餅', qty: 1, price: 45, subtotal: 45 },
      { name: '小杯豆漿', qty: 1, price: 20, subtotal: 20 }
    ]
  },
  {
    orderId: today + '-0006',
    customerName: '黃雅婷', phone: '0967890123',
    dineIn: true, tableNo: 'A1', status: 'done',
    totalWithTax: 126,
    validItems: [
      { name: '鮪魚蛋餅', qty: 1, price: 55, subtotal: 55 },
      { name: '培根起司堡', qty: 1, price: 65, subtotal: 65 }
    ]
  }
];

// 符合後續「日結統計計算」節點期望的輸出格式
return mockOrders.map(order => ({ json: order }));

// ═══════════════════════════════════════════════════════
// 日結流程 節點③：日結統計計算
// 功能：統計當日銷售數據、品項排行、整理報表資料
// ═══════════════════════════════════════════════════════
const allOrders = $input.all().map(i => i.json);
const dateStr   = new Date().toLocaleDateString('zh-TW', {
  timeZone: 'Asia/Taipei', year: 'numeric', month: '2-digit', day: '2-digit'
});

// 無訂單時回傳空報表
if (allOrders.length === 0) {
  return [{ json: {
    reportDate:      dateStr,
    totalCount:      0, completedCount: 0, cancelledCount: 0,
    completionRate:  0,
    totalRevenue:    0, formattedRevenue: 'NT$0',
    avgOrderValue:   0, formattedAvg: 'NT$0',
    maxAmount:       0, minAmount: 0,
    topItems:        [], topItemsSummary: '今日無訂單',
    generatedAt:     new Date().toISOString()
  }}];
}

const done      = allOrders.filter(o => o.status === 'done');
const cancelled = allOrders.filter(o => o.status === 'cancelled');
const revenues  = done.map(o => o.totalWithTax || 0);

const total    = revenues.reduce((s, v) => s + v, 0);
const avg      = done.length ? Math.round(total / done.length) : 0;
const maxAmt   = revenues.length ? Math.max(...revenues) : 0;
const minAmt   = revenues.length ? Math.min(...revenues) : 0;
const rate     = Math.round(done.length / allOrders.length * 100);

// 品項銷售統計
const itemMap = {};
done.forEach(o => (o.validItems || []).forEach(it => {
  if (!itemMap[it.name]) itemMap[it.name] = { name: it.name, qty: 0, rev: 0 };
  itemMap[it.name].qty += it.qty      || 0;
  itemMap[it.name].rev += it.subtotal || 0;
}));

// 前 5 名（依數量降序）
const topItems = Object.values(itemMap)
  .sort((a, b) => b.qty - a.qty).slice(0, 5)
  .map((it, i) => ({
    rank:            i + 1,
    name:            it.name,
    totalQty:        it.qty,
    totalRevenue:    it.rev,
    formattedRevenue: 'NT$' + it.rev.toLocaleString('zh-TW')
  }));

return [{ json: {
  reportDate:      dateStr,
  totalCount:      allOrders.length,
  completedCount:  done.length,
  cancelledCount:  cancelled.length,
  completionRate:  rate,
  totalRevenue:    total,
  formattedRevenue: 'NT$' + total.toLocaleString('zh-TW'),
  avgOrderValue:   avg,
  formattedAvg:    'NT$' + avg.toLocaleString('zh-TW'),
  maxAmount:       maxAmt,
  minAmount:       minAmt,
  topItems,
  topItemsSummary: topItems.map(i =>
    i.rank + '. ' + i.name + '（' + i.totalQty + ' 份）'
  ).join(' | '),
  generatedAt: new Date().toISOString()
}}];
